export function SettingsPage() {
  const { data, setData, notify } = useWorkspace(); const [tab, setTab] = useState("overview"); const [testing, setTesting] = useState(false); const [connection, setConnection] = useState(""); const [catalog, setCatalog] = useState<AiCatalog | null>(null); const [catalogError, setCatalogError] = useState(""); const prefs = data.preferences;
  useEffect(() => { let mounted = true; void getAiCatalog().then(value => { if (mounted) { setCatalog(value); setCatalogError(""); } }).catch(error => { if (mounted) setCatalogError(error instanceof Error ? error.message : String(error)); }); return () => { mounted = false; }; }, []);
  function update(field: keyof typeof prefs, value: string | boolean) { setData(d => ({ ...d, preferences: { ...d.preferences, [field]: value } })); }
  function testConnection(name: string) { setConnection(name); setTesting(true); setTimeout(() => { setTesting(false); notify(`${name}: comprobación simulada completada.`); }, 900); }
  async function refreshAiCatalog() { setConnection("IA"); setTesting(true); try { setCatalog(await getAiCatalog()); setCatalogError(""); notify("Catálogo de runtimes actualizado."); } catch (error) { setCatalogError(error instanceof Error ? error.message : String(error)); notify("No se pudo consultar el catálogo de IA."); } finally { setTesting(false); } }
  const runtime = (prefs.runtime || "opencode") as AiRuntime;
  const runtimeCatalog = catalog?.[runtime];
  const runtimeStatus = catalog?.runtimes.find(item => item.id === runtime);
  const tabs = [{ id: "overview", label: "Resumen" }, { id: "ai", label: "Inteligencia artificial" }, { id: "credentials", label: "Usuarios de prueba" }, { id: "project", label: "Proyecto y código" }, { id: "devices", label: "Dispositivos" }, { id: "mcp", label: "Integraciones MCP" }, { id: "jira", label: "Jira" }];
  return <div className="page-content"><PageHeading eyebrow="WORKSPACE" title="Configuración" description="Administra el entorno, las integraciones y las preferencias del equipo." actions={<><Button onClick={() => setData(d => ({ ...d, preferences: { ...seedPreferences } }))}>Restablecer</Button><Button variant="primary" icon="check" onClick={() => notify("Preferencias guardadas en este navegador.")}>Guardar cambios</Button></>} /><div className="settings-status"><span className="status-check"><Icon name="check" size={17} /></span><div><strong>Workspace local listo para explorar</strong><small>Las preferencias y los IDs de sesión se guardan en este navegador.</small></div><Badge tone="green">API conectada</Badge></div><div className="settings-layout"><nav className="settings-tabs" aria-label="Ajustes de configuración">{tabs.map(t => <button key={t.id} className={tab === t.id ? "active" : ""} onClick={() => setTab(t.id)}>{t.label}<Icon name="chevron" size={15} /></button>)}</nav><section className="settings-content">
     {tab === "overview" && <><div className="section-heading"><div><h2>Resumen del entorno</h2><p>Revisa los datos básicos que utilizará la aplicación.</p></div><Button onClick={() => testConnection("Entorno local")} icon="refresh">{testing && connection === "Entorno local" ? "Validando…" : "Validar entorno"}</Button></div><div className="settings-summary-grid"><div><span>Proyecto</span><strong>{prefs.projectName || "Sin definir"}</strong></div><div><span>Entorno</span><strong>{prefs.environment}</strong></div><div><span>Base URL</span><strong>{prefs.baseUrl || "Sin definir"}</strong></div><div><span>Agente IA</span><strong>{prefs.provider} · {prefs.agent || "predeterminado"}</strong></div></div><div className="checklist"><div><span className="checklist-dot good"><Icon name="check" size={12} /></span><div><strong>Catálogo de casos</strong><small>{data.cases.length} casos disponibles</small></div><Badge tone="green">Local</Badge></div><div><span className="checklist-dot warn"><Icon name="clock" size={12} /></span><div><strong>Runner de navegador</strong><small>Conectado a través del backend</small></div><Badge tone="green">Backend</Badge></div><div><span className={`checklist-dot ${runtimeStatus?.available ? "good" : "warn"}`}><Icon name={runtimeStatus?.available ? "check" : "clock"} size={12} /></span><div><strong>Runtime de IA</strong><small>{runtimeStatus?.available ? `${runtimeStatus.name} disponible` : runtimeStatus?.error || "Consultando catálogo…"}</small></div><Badge tone={runtimeStatus?.available ? "green" : "amber"}>{runtimeStatus?.available ? "Disponible" : "No disponible"}</Badge></div></div></>}
     {tab === "ai" && <><div className="section-heading"><div><h2>Agente y modelo</h2><p>Selecciona un runtime y un agente configurado en OpenCode o Claude Code.</p></div><Button icon="refresh" onClick={() => void refreshAiCatalog()}>{testing && connection === "IA" ? "Actualizando…" : "Actualizar catálogo"}</Button></div>{catalogError && <div className="info-notice" role="alert"><Icon name="shield" size={18} /><span>{catalogError}</span></div>}<div className="form-grid"><Field label="Runtime"><select value={runtime} onChange={e => { const selectedRuntime = e.target.value as AiRuntime; update("runtime", selectedRuntime); update("provider", selectedRuntime === "native" ? "Agent Tester" : selectedRuntime === "claude" ? "Claude Agent" : "OpenCode"); update("agent", ""); update("aiModel", ""); }}><option value="opencode">OpenCode{catalog?.runtimes.find(item => item.id === "opencode")?.available ? " · disponible" : " · sin conexión"}</option><option value="claude">Claude Agent{catalog?.runtimes.find(item => item.id === "claude")?.available ? " · disponible" : " · sin autenticación"}</option><option value="native">Agent Tester{catalog?.runtimes.find(item => item.id === "native")?.available ? " · disponible" : " · requiere API key"}</option></select></Field><Field label="Agente"><select value={prefs.agent} onChange={e => update("agent", e.target.value)}><option value="">Predeterminado del runtime</option>{runtimeCatalog?.agents.map(agent => <option key={agent.id} value={agent.id}>{agent.name}</option>)}</select></Field><Field label="Modelo"><select value={prefs.aiModel} onChange={e => update("aiModel", e.target.value)}><option value="">Modelo predeterminado</option>{runtimeCatalog?.models.map(model => <option key={model.id} value={model.id}>{model.name}{model.local ? " · local" : ""}</option>)}</select></Field></div><div className="info-notice"><Icon name="shield" size={18} /><span>OpenCode utiliza los agentes, modelos y autenticación de su propia configuración. Claude reutiliza los agentes configurados en Claude Code. Las credenciales permanecen en el servidor y no se guardan en el navegador.</span></div><h3 className="settings-subhead">Estado del runtime</h3><p className="context-copy">{runtimeStatus?.available ? `${runtimeStatus.name} conectado.` : runtimeStatus?.error || "El estado se actualizará al consultar el catálogo."}</p><h3 className="settings-subhead">Usos</h3><label className="check-row"><input type="checkbox" defaultChecked /> Generar casos desde criterios de aceptación</label><label className="check-row"><input type="checkbox" defaultChecked /> Proponer escenarios negativos y límites</label><label className="check-row"><input type="checkbox" defaultChecked /> Analizar fallos y sugerir correcciones</label></>}
    {tab === "credentials" && <><div className="section-heading"><div><h2>Usuarios de prueba</h2><p>Referencias locales sin credenciales reales.</p></div><Button variant="primary" icon="plus" onClick={() => notify("El alta de usuarios se habilitará al conectar el almacenamiento seguro.")}>Agregar usuario</Button></div><div className="settings-empty-card"><span className="assistant-spark"><Icon name="shield" size={18} /></span><div><strong>No hay credenciales guardadas</strong><p>Por seguridad, las credenciales no se almacenan en el navegador. Configura usuarios de prueba a través del backend.</p></div></div></>}
    {tab === "project" && <><div className="section-heading"><div><h2>Proyecto y repositorio</h2><p>Identifica el proyecto y la URL base de las pruebas.</p></div></div><div className="form-stack"><Field label="Nombre del proyecto"><input value={prefs.projectName} onChange={e => update("projectName", e.target.value)} /></Field><Field label="URL base del entorno"><input type="url" value={prefs.baseUrl} onChange={e => update("baseUrl", e.target.value)} placeholder="http://localhost:3002" /></Field><Field label="Repositorio GitHub"><input value={prefs.repo} onChange={e => update("repo", e.target.value)} placeholder="organización/repositorio" /></Field><Field label="Rama de trabajo"><input value={prefs.branch} onChange={e => update("branch", e.target.value)} /></Field></div><div className="info-notice"><Icon name="code" size={18} /><span>Las vistas de código se generan como previsualizaciones. La modificación de un repositorio requiere el servicio MCP/server.</span></div></>}
    {tab === "devices" && <><div className="section-heading"><div><h2>Dispositivos de prueba</h2><p>Disponibilidad indicativa de motores para la integración.</p></div><Button variant="primary" icon="plus" onClick={() => notify("Los dispositivos se administrarán desde la configuración del runner.")}>Agregar dispositivo</Button></div><div className="device-list"><div><span className="device-icon"><Icon name="monitor" size={19} /></span><div><strong>Chrome Desktop</strong><small>Navegador web · viewport escritorio</small></div><Badge tone={prefs.chrome ? "green" : "neutral"}>{prefs.chrome ? "Habilitado" : "Deshabilitado"}</Badge><button className={`switch ${prefs.chrome ? "on" : ""}`} aria-label="Activar Chrome Desktop" aria-pressed={prefs.chrome} onClick={() => update("chrome", !prefs.chrome)}><i /></button></div><div><span className="device-icon"><Icon name="monitor" size={19} /></span><div><strong>Appium · Móvil</strong><small>Integración MCP móvil · Android / iOS</small></div><Badge tone={prefs.appium ? "green" : "amber"}>{prefs.appium ? "Habilitado" : "No configurado"}</Badge><button className={`switch ${prefs.appium ? "on" : ""}`} aria-label="Activar integración Appium" aria-pressed={prefs.appium} onClick={() => update("appium", !prefs.appium)}><i /></button></div></div></>}
    {tab === "mcp" && <><div className="section-heading"><div><h2>Integraciones MCP</h2><p>Conexiones previstas para inspección y automatización.</p></div><Badge tone="amber">Servidor local</Badge></div><div className="integration-card"><div className="integration-head"><span className="device-icon"><Icon name="globe" size={19} /></span><div><strong>Agent Tester MCP</strong><small>Herramientas de documentación y ejecución</small></div><Badge tone="amber">Backend pendiente</Badge></div><Field label="Endpoint"><input value={prefs.mcpUrl} onChange={e => update("mcpUrl", e.target.value)} /></Field><div className="integration-footer"><span className="muted-text">El cliente MCP existente está en modo scaffold.</span><Button icon="refresh" onClick={() => testConnection("MCP")}>{testing && connection === "MCP" ? "Comprobando…" : "Probar conexión"}</Button></div></div><div className="integration-card"><div className="integration-head"><span className="device-icon"><Icon name="bug" size={19} /></span><div><strong>Jira MCP</strong><small>Lectura de requisitos y seguimiento de bugs</small></div><Badge tone={prefs.jiraUrl ? "blue" : "amber"}>{prefs.jiraUrl ? "Configurado" : "Sin configurar"}</Badge></div><Field label="Endpoint Jira"><input value={prefs.jiraUrl} onChange={e => update("jiraUrl", e.target.value)} placeholder="https://tu-organizacion.atlassian.net" /></Field></div></>}
    {tab === "jira" && <JiraSettingsPanel />}
       {tab === "ai" && <div className="info-notice"><Icon name="play" size={18} /><span>Runner E2E: {catalog?.e2e.available ? `${catalog.e2e.provider} · ${catalog.e2e.model}${catalog.e2e.local ? " · endpoint compatible configurado sin clave" : ""}` : catalog?.e2e.error || "consultando configuración"}. El runner usa su modelo de ejecución configurado en el servidor.</span></div>}
     </section></div></div>;
}
function JiraSettingsPanel() {
  const { setData, notify } = useWorkspace();
  const [connection, setConnection] = useState<{ configured: boolean; projectKey: string; baseUrl: string; email: string } | null>(null);
  const [form, setForm] = useState({ baseUrl: "", email: "", apiToken: "", projectKey: "" });
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    let active = true;
    void api.getJiraConnection().then((value) => {
      if (!active) return;
      setConnection(value);
      setForm({ baseUrl: value.baseUrl, email: value.email, apiToken: "", projectKey: value.projectKey });
    }).catch((cause) => { if (active) setError(cause instanceof Error ? cause.message : "No se pudo leer la configuración Jira."); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []);
  function update(field: keyof typeof form, value: string) { setForm((current) => ({ ...current, [field]: value })); }
  function payload() { return { ...form, baseUrl: form.baseUrl.trim(), email: form.email.trim(), projectKey: form.projectKey.trim().toUpperCase(), apiToken: form.apiToken.trim() || undefined }; }
  async function test() {
    setBusy(true); setError("");
    try { const result = await api.testJiraConnection(payload()); notify(`Jira conectado correctamente al proyecto ${result.projectKey}.`); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Falló la validación de Jira."); }
    finally { setBusy(false); }
  }
  async function save() {
    setBusy(true); setError("");
    try {
      const saved = await api.saveJiraConnection(payload());
      setConnection(saved); setForm((current) => ({ ...current, apiToken: "" }));
      setData((data) => ({ ...data, preferences: { ...data.preferences, jiraUrl: saved.baseUrl, jiraProject: saved.projectKey } }));
      notify(`Conexión Jira guardada para ${saved.projectKey}.`);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo guardar la conexión Jira."); }
    finally { setBusy(false); }
  }
  async function disconnect() {
    setBusy(true); setError("");
    try {
      await api.deleteJiraConnection(); setConnection({ configured: false, baseUrl: "", email: "", projectKey: "" });
      setForm({ baseUrl: "", email: "", apiToken: "", projectKey: "" });
      setData((data) => ({ ...data, preferences: { ...data.preferences, jiraUrl: "", jiraProject: "" } }));
      notify("Jira se desconectó y se eliminó el token cifrado.");
    } catch (cause) { setError(cause instanceof Error ? cause.message : "No se pudo desconectar Jira."); }
    finally { setBusy(false); }
  }
  if (loading) return <div className="loading-state">Cargando configuración Jira…</div>;
  return <>
    <div className="section-heading"><div><h2>Jira Cloud</h2><p>Configura una conexión de solo lectura para obtener tickets desde Generación IA.</p></div><Badge tone={connection?.configured ? "green" : "amber"}>{connection?.configured ? `Conectado · ${connection.projectKey}` : "Sin conexión"}</Badge></div>
    {error && <div className="info-notice jira-error" role="alert"><Icon name="shield" size={18} /><span>{error}</span></div>}
    <div className="form-stack jira-settings-form">
      <Field label="URL del sitio Jira Cloud"><input type="url" value={form.baseUrl} onChange={(event) => update("baseUrl", event.target.value)} placeholder="https://tu-organizacion.atlassian.net" autoComplete="url" /></Field>
      <Field label="Email de Atlassian"><input type="email" value={form.email} onChange={(event) => update("email", event.target.value)} placeholder="qa@empresa.com" autoComplete="username" /></Field>
      <Field label="Clave del proyecto"><input value={form.projectKey} onChange={(event) => update("projectKey", event.target.value.toUpperCase())} placeholder="PROY" autoCapitalize="characters" /></Field>
      <Field label={connection?.configured ? "API token (vacío = conservar el token guardado)" : "API token de Atlassian"}><input type="password" value={form.apiToken} onChange={(event) => update("apiToken", event.target.value)} placeholder={connection?.configured ? "•••••••••••• (guardado cifrado)" : "Pega aquí el API token"} autoComplete="new-password" /></Field>
    </div>
    <div className="info-notice"><Icon name="shield" size={18} /><span>El token se cifra en el servidor y nunca se devuelve ni se guarda en este navegador. Genera un API token de Atlassian con permisos de lectura para el proyecto.</span></div>
    <div className="actions jira-settings-actions"><Button icon="refresh" disabled={busy || !form.baseUrl || !form.email || !form.projectKey} onClick={() => void test()}>{busy ? "Validando…" : "Probar conexión"}</Button><Button variant="primary" icon="check" disabled={busy || !form.baseUrl || !form.email || !form.projectKey} onClick={() => void save()}>{busy ? "Guardando…" : "Guardar conexión"}</Button>{connection?.configured && <Button variant="danger" disabled={busy} onClick={() => void disconnect()}>Desconectar</Button>}</div>
  </>;
}
const seedPreferences = { environment: "Local", projectName: "Demo Shop", baseUrl: "http://localhost:3002", provider: "OpenCode", model: "Predeterminado", runtime: "opencode" as const, agent: "", aiModel: "", repo: "", branch: "main", jiraUrl: "", jiraProject: "SHOP", chrome: true, appium: false, mcpUrl: "http://localhost:3001/mcp" };
export function NotFoundPage() { return <div className="page-content"><EmptyState title="Esta página no existe" description="El enlace no corresponde a una sección de TESTEALO." icon="search"><Link className="btn btn-primary" to="/">Volver al resumen</Link></EmptyState></div>; }
